import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState, useEffect } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();
  const [polls, setPolls] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [category, setCategory] = useState("all");

  useEffect(() => {
    fetchPolls();
    fetchSurveys();
  }, []);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch (err) { console.log("Poll error", err); }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch (err) { console.log("Survey error", err); }
  };

  return (
    <>
      <Navbar />

      <style>{`
        .home-container {
          min-height: 100vh;
          padding: 40px;
          color: white;
          background: #020617; /* Deep space black */
          background-image: 
            radial-gradient(circle at 20% 20%, rgba(59, 130, 246, 0.15) 0%, transparent 40%),
            radial-gradient(circle at 80% 80%, rgba(147, 51, 234, 0.1) 0%, transparent 40%);
          font-family: 'Inter', sans-serif;
        }

        .header-section {
          text-align: center;
          margin-bottom: 50px;
        }

        .header-section h1 {
          font-size: 32px;
          letter-spacing: 2px;
          text-transform: uppercase;
          background: linear-gradient(to right, #60a5fa, #a78bfa);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
        }

        .nav-pills {
          display: flex;
          justify-content: center;
          gap: 15px;
          background: rgba(255, 255, 255, 0.05);
          width: fit-content;
          margin: 20px auto;
          padding: 8px;
          border-radius: 30px;
          backdrop-filter: blur(10px);
          border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .nav-pills button {
          padding: 8px 24px;
          border: none;
          background: transparent;
          color: #94a3b8;
          cursor: pointer;
          transition: 0.3s;
          border-radius: 20px;
          font-weight: 500;
        }

        .nav-pills .active {
          background: rgba(59, 130, 246, 0.2);
          color: #60a5fa;
          box-shadow: 0 0 15px rgba(59, 130, 246, 0.3);
        }

        .dashboard-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
          gap: 30px;
          max-width: 1200px;
          margin: 0 auto;
        }

        .glass-card {
          background: rgba(255, 255, 255, 0.03);
          backdrop-filter: blur(12px);
          border: 1px solid rgba(255, 255, 255, 0.1);
          border-radius: 24px;
          padding: 30px;
          position: relative;
          transition: transform 0.3s ease;
        }

        .glass-card:hover {
          transform: translateY(-5px);
          border-color: rgba(59, 130, 246, 0.4);
        }

        .card-title {
          font-size: 14px;
          color: #94a3b8;
          text-transform: uppercase;
          letter-spacing: 1.5px;
          margin-bottom: 25px;
          display: flex;
          align-items: center;
          gap: 10px;
        }

        .item-row {
          background: rgba(255, 255, 255, 0.03);
          border: 1px solid rgba(255, 255, 255, 0.05);
          padding: 15px 20px;
          border-radius: 14px;
          margin-bottom: 12px;
          cursor: pointer;
          display: flex;
          justify-content: space-between;
          align-items: center;
          transition: 0.2s;
        }

        .item-row:hover {
          background: rgba(59, 130, 246, 0.1);
          border-color: #3b82f6;
        }

        .btn-action {
          width: 100%;
          padding: 14px;
          margin-top: 15px;
          border-radius: 12px;
          border: none;
          font-weight: 600;
          cursor: pointer;
          background: linear-gradient(45deg, #3b82f6, #2563eb);
          color: white;
          box-shadow: 0 4px 15px rgba(37, 99, 235, 0.3);
          transition: 0.3s;
        }

        .btn-action:hover {
          filter: brightness(1.1);
          box-shadow: 0 0 20px rgba(59, 130, 246, 0.5);
        }

        .orange-glow { border-bottom: 3px solid #f97316; }
        .blue-glow { border-bottom: 3px solid #3b82f6; }
      `}</style>

      <div className="home-container">
        <div className="header-section">
          <h1>Tek Surveys & Polls</h1>
          
          <div className="nav-pills">
            {["all", "student", "teacher", "general"].map(cat => (
              <button
                key={cat}
                className={category === cat ? "active" : ""}
                onClick={() => setCategory(cat)}
              >
                {cat.charAt(0).toUpperCase() + cat.slice(1)}
              </button>
            ))}
          </div>
        </div>

        <div className="dashboard-grid">
          {/* POLLS SECTION */}
          <div className="glass-card orange-glow">
            <div className="card-title"><span>📊</span> Active Polls</div>
            {polls.slice(0, 3).map(p => (
              <div key={p._id} className="item-row" onClick={() => nav(`/poll/${p._id}`)}>
                {p.question}
                <span style={{color: '#f97316', fontSize: '12px'}}>VIEW</span>
              </div>
            ))}
            <button className="btn-action" style={{background: 'linear-gradient(45deg, #f97316, #ea580c)'}} onClick={() => nav("/create-poll")}>
              CREATE NEW POLL
            </button>
          </div>

          {/* SURVEYS SECTION */}
          <div className="glass-card blue-glow">
            <div className="card-title"><span>📝</span> Recent Surveys</div>
            {surveys
              .filter(s => category === "all" || (s.category || "").toLowerCase() === category)
              .slice(0, 3)
              .map(s => (
                <div key={s._id} className="item-row" onClick={() => nav(`/survey/${s._id}`)}>
                  {s.title}
                  <span style={{color: '#60a5fa', fontSize: '12px'}}>TAKE</span>
                </div>
              ))}
            <button className="btn-action" onClick={() => nav("/create-survey")}>
              GIVE FEEDBACK
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
